const flota = 500;
const intervalos = [1, 5, 10, 30, 60];      // segundos entre reportes
const BYTES_DATO = 100;                    // un reporte en JSON, sin envoltorio (estimación)
const BYTES_CON_ENVOLTORIO = 500;          // con encabezados de la petición (estimación)

for (const s of intervalos) {
  const reportesDia = (86400 / s) * flota;
  const soloDatos = reportesDia * BYTES_DATO / 1e6;            // en MB (decimal)
  const conEnvoltorio = reportesDia * BYTES_CON_ENVOLTORIO / 1e9; // en GB (decimal)
  console.log(`cada ${s} s: ${reportesDia.toLocaleString("es-AR")} reportes/día · ${soloDatos.toLocaleString("es-AR")} MB/día de datos · ${conEnvoltorio.toLocaleString("es-AR")} GB/día con envoltorio`);
}

// Una sola camioneta, un mes, con envoltorio, cada 10 s
const porSim = (86400 / 10) * BYTES_CON_ENVOLTORIO * 30 / 1e6;
console.log(`por SIM y por mes (cada 10 s): ${porSim.toLocaleString("es-AR")} MB`);
